INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3140702_2024_001','GTU',1,0,NULL,'gtu_dataset_3140702_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3140702','Operating System',4,NULL,1,'OS Architecture & System Calls',NULL,'MCQ','Which mode transition occurs when a user application executes a system call (e.g. read() or fork()) in a dual-mode operating system?',NULL,NULL,'[{"id":"A","text":"Kernel mode to user mode via software interrupt"},{"id":"B","text":"User mode to kernel mode via software trap/interrupt"},{"id":"C","text":"Privileged mode to guest mode"},{"id":"D","text":"Virtual memory mode to physical memory mode"}]','"B"',NULL,'When an application issues a system call, the CPU generates a software interrupt or trap instruction (e.g. syscall/int 0x80) that switches the processor state from user mode (ring 3) to kernel/supervisor mode (ring 0) to execute the privileged OS service.',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','educator_admin','2026-08-26 18:24:30','2026-08-26 18:24:30','2026-08-26 18:24:30');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3140702_2023_002','GTU',1,0,NULL,'gtu_dataset_3140702_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'3140702','Operating System',4,NULL,1,'OS Architecture & System Calls',NULL,'MCQ','What is the primary advantage of a Microkernel architecture (e.g., Mach, QNX) compared to a Monolithic kernel (e.g., Linux)?',NULL,NULL,'[{"id":"A","text":"Faster context switching and zero IPC overhead"},{"id":"B","text":"Higher modularity, fault isolation, and easier system extensibility"},{"id":"C","text":"Direct hardware access from all user processes"},{"id":"D","text":"Elimination of virtual memory requirements"}]','"B"',NULL,'A microkernel moves non-essential components (file systems, device drivers, network protocols) into user space servers. This improves security and fault isolation because a crash in a device driver does not crash the entire operating system kernel.',NULL,NULL,0,NULL,1,0.25,'medium','ANALYZE',NULL,'verified','educator_admin','2026-08-26 18:24:30','2026-08-26 18:24:30','2026-08-26 18:24:30');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3140702_2024_003','GTU',1,0,NULL,'gtu_dataset_3140702_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3140702','Operating System',4,NULL,2,'CPU Scheduling Algorithms',NULL,'MCQ','Which CPU scheduling algorithm is provably optimal with respect to minimizing average waiting time for a given set of stationary processes?',NULL,NULL,'[{"id":"A","text":"First-Come, First-Served (FCFS)"},{"id":"B","text":"Shortest Job First (SJF / Shortest Remaining Time First)"},{"id":"C","text":"Round Robin (RR) with time quantum $q = 10\\text{ ms}$"},{"id":"D","text":"Priority Scheduling with Aging"}]','"B"',NULL,'Shortest Job First (SJF) scheduling is provably optimal because scheduling shorter burst jobs before longer ones minimizes the queue delay accumulated across subsequent processes, yielding minimum average waiting time.',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','educator_admin','2026-08-26 18:24:30','2026-08-26 18:24:30','2026-08-26 18:24:30');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3140702_2023_004','GTU',1,0,NULL,'gtu_dataset_3140702_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'3140702','Operating System',4,NULL,2,'CPU Scheduling Algorithms',NULL,'MCQ','In Round Robin (RR) CPU scheduling, what occurs when the time quantum is chosen to be extremely large ($q \rightarrow \infty$)?',NULL,NULL,'[{"id":"A","text":"The scheduler degenerates into First-Come, First-Served (FCFS)"},{"id":"B","text":"Process starvation occurs for short burst tasks"},{"id":"C","text":"CPU utilization drops to zero due to excessive thrashing"},{"id":"D","text":"Context switch frequency reaches maximum limits"}]','"A"',NULL,'When the time quantum $q$ is greater than the longest burst time of any ready process, no process is ever preempted before completion. Consequently, processes run to completion in arrival order, degenerating directly into FCFS scheduling.',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','educator_admin','2026-08-26 18:24:30','2026-08-26 18:24:30','2026-08-26 18:24:30');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3140702_2024_005','GTU',1,0,NULL,'gtu_dataset_3140702_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3140702','Operating System',4,NULL,2,'CPU Scheduling Algorithms',NULL,'MCQ','Consider 3 processes $P_1, P_2, P_3$ arriving at time $t=0$ with burst times $24\text{ ms}, 3\text{ ms}, 3\text{ ms}$. Under non-preemptive SJF, what is the average waiting time?',NULL,NULL,'[{"id":"A","text":"3.0 ms"},{"id":"B","text":"5.0 ms"},{"id":"C","text":"6.0 ms"},{"id":"D","text":"17.0 ms"}]','"A"',NULL,'Execution order under SJF is $P_2 (0\text{--}3\text{ ms}) \rightarrow P_3 (3\text{--}6\text{ ms}) \rightarrow P_1 (6\text{--}30\text{ ms})$. Waiting times: $W(P_2)=0\text{ ms}$, $W(P_3)=3\text{ ms}$, $W(P_1)=6\text{ ms}$. Average waiting time $= (0 + 3 + 6) / 3 = 9 / 3 = 3.0\text{ ms}$.',NULL,NULL,0,NULL,1,0.25,'medium','APPLY',NULL,'verified','educator_admin','2026-08-26 18:24:30','2026-08-26 18:24:30','2026-08-26 18:24:30');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3140702_2024_006','GTU',1,0,NULL,'gtu_dataset_3140702_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3140702','Operating System',4,NULL,3,'Critical Section Problem & Semaphores',NULL,'MCQ','Which three critical requirements must any valid software or hardware solution to the Critical Section problem satisfy?',NULL,NULL,'[{"id":"A","text":"Mutual Exclusion, Progress, and Bounded Waiting"},{"id":"B","text":"Deadlock Prevention, Starvation Freedom, and Paging"},{"id":"C","text":"Atomicity, Consistency, and Isolation"},{"id":"D","text":"Preemption, Aging, and Context Switching"}]','"A"',NULL,'Dijkstra and Silberschatz state the 3 fundamental requirements for critical section solutions: 1. Mutual Exclusion (at most one process inside CS), 2. Progress (selection of next entrant cannot be postponed indefinitely), 3. Bounded Waiting (bound on the number of times others enter CS before a waiting process).',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','educator_admin','2026-08-26 18:24:30','2026-08-26 18:24:30','2026-08-26 18:24:30');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3140702_2023_007','GTU',1,0,NULL,'gtu_dataset_3140702_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'3140702','Operating System',4,NULL,3,'Critical Section Problem & Semaphores',NULL,'MCQ','A counting semaphore $S$ is initialized to 10. If 12 $\text{wait}(S)$ operations and 5 $\text{signal}(S)$ operations are executed, what is the final integer value of $S$?',NULL,NULL,'[{"id":"A","text":"3"},{"id":"B","text":"-2"},{"id":"C","text":"7"},{"id":"D","text":"0"}]','"A"',NULL,'Value of semaphore after operations is $S_{\text{final}} = S_{\text{initial}} - (\text{number of waits}) + (\text{number of signals}) = 10 - 12 + 5 = 3$.',NULL,NULL,0,NULL,1,0.25,'medium','APPLY',NULL,'verified','educator_admin','2026-08-26 18:24:30','2026-08-26 18:24:30','2026-08-26 18:24:30');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3140702_2024_008','GTU',1,0,NULL,'gtu_dataset_3140702_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3140702','Operating System',4,NULL,3,'Critical Section Problem & Semaphores',NULL,'MCQ','Which of the following conditions is NOT one of Coffman''s four necessary conditions for a deadlock to occur?',NULL,NULL,'[{"id":"A","text":"Mutual Exclusion"},{"id":"B","text":"Hold and Wait"},{"id":"C","text":"Preemptive Resource Allocation"},{"id":"D","text":"Circular Wait"}]','"C"',NULL,'The four necessary conditions for deadlock are: 1. Mutual Exclusion, 2. Hold and Wait, 3. No Preemption (resources cannot be preempted), and 4. Circular Wait. Preemptive resource allocation actually prevents deadlocks.',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','educator_admin','2026-08-26 18:24:30','2026-08-26 18:24:30','2026-08-26 18:24:30');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3140702_2023_009','GTU',1,0,NULL,'gtu_dataset_3140702_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'3140702','Operating System',4,NULL,3,'Critical Section Problem & Semaphores',NULL,'MCQ','Banker''s Algorithm in an operating system is utilized for which specific purpose?',NULL,NULL,'[{"id":"A","text":"Deadlock Detection and Recovery"},{"id":"B","text":"Deadlock Avoidance using Safe State Analysis"},{"id":"C","text":"Mutual Exclusion Enforcement"},{"id":"D","text":"Page Replacement Selection"}]','"B"',NULL,'Dijkstra''s Banker''s algorithm is a deadlock avoidance algorithm. It dynamically tests for safety by simulating resource allocations before granting them to ensure the system never enters an unsafe state.',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','educator_admin','2026-08-26 18:24:30','2026-08-26 18:24:30','2026-08-26 18:24:30');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3140702_2024_010','GTU',1,0,NULL,'gtu_dataset_3140702_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3140702','Operating System',4,NULL,4,'Paging & Page Replacement Algorithms',NULL,'MCQ','In a paging system with 32-bit virtual addresses and a $4\text{ KB}$ ($2^{12}\text{ bytes}$) page size, how many total entries are present in a flat single-level page table?',NULL,NULL,'[{"id":"A","text":"$2^{12} = 4096$"},{"id":"B","text":"$2^{20} = 1,048,576$"},{"id":"C","text":"$2^{32}$"},{"id":"D","text":"$2^{16} = 65,536$"}]','"B"',NULL,'With a 32-bit address and $4\text{ KB} = 2^{12}\text{ bytes}$ page size, 12 bits are allocated for the page offset $(d)$. The remaining $32 - 12 = 20$ bits define the page number $(p)$. Thus, the page table contains $2^{20} = 1,048,576$ entries.',NULL,NULL,0,NULL,1,0.25,'medium','APPLY',NULL,'verified','educator_admin','2026-08-26 18:24:30','2026-08-26 18:24:30','2026-08-26 18:24:30');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3140702_2024_011','GTU',1,0,NULL,'gtu_dataset_3140702_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3140702','Operating System',4,NULL,4,'Paging & Page Replacement Algorithms',NULL,'MCQ','What is Belady''s Anomaly in operating systems virtual memory management?',NULL,NULL,'[{"id":"A","text":"Page fault rate increases as the number of allocated physical frames increases under FIFO"},{"id":"B","text":"LRU page replacement causes thrashing on circular reference loops"},{"id":"C","text":"TLB hit ratio drops to zero when page tables are inverted"},{"id":"D","text":"Demand paging requires double disk bandwidth under multi-threading"}]','"A"',NULL,'Belady''s Anomaly is the phenomenon in which allocating more physical page frames results in an increased number of page faults for certain reference strings under the First-In, First-Out (FIFO) page replacement policy.',NULL,NULL,0,NULL,1,0.25,'medium','UNDERSTAND',NULL,'verified','educator_admin','2026-08-26 18:24:30','2026-08-26 18:24:30','2026-08-26 18:24:30');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3130702_2024_012','GTU',1,0,NULL,'gtu_dataset_3130702_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3130702','Data Structures',3,NULL,1,'Stacks & Queues',NULL,'MCQ','What is the minimum number of single-ended queues required to implement a Last-In, First-Out (LIFO) Stack?',NULL,NULL,'[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}]','"B"',NULL,'To simulate a Stack using Queues, 2 queues are required ($q_1$ and $q_2$). During push/pop, elements are dequeued and enqueued between queues to reverse the FIFO order to LIFO.',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','educator_admin','2026-08-26 18:24:30','2026-08-26 18:24:30','2026-08-26 18:24:30');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3130702_2024_013','GTU',1,0,NULL,'gtu_dataset_3130702_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3130702','Data Structures',3,NULL,1,'Stacks & Queues',NULL,'MCQ','What is the postfix evaluation result of the arithmetic expression: `6 3 2 + * 5 -`?',NULL,NULL,'[{"id":"A","text":"25"},{"id":"B","text":"30"},{"id":"C","text":"20"},{"id":"D","text":"15"}]','"A"',NULL,'1. Push 6, 3, 2. 2. Encounter `+`: pop 2, 3 $\rightarrow 3 + 2 = 5$, push 5. 3. Encounter `*`: pop 5, 6 $\rightarrow 6 \times 5 = 30$, push 30. 4. Push 5. 5. Encounter `-`: pop 5, 30 $\rightarrow 30 - 5 = 25$. Result $= 25$.',NULL,NULL,0,NULL,1,0.25,'medium','APPLY',NULL,'verified','educator_admin','2026-08-26 18:24:30','2026-08-26 18:24:30','2026-08-26 18:24:30');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3130702_2024_014','GTU',1,0,NULL,'gtu_dataset_3130702_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3130702','Data Structures',3,NULL,2,'Binary Search Trees & AVL Trees',NULL,'MCQ','In an AVL Tree, what is the strictly permissible balance factor range for every node in the tree?',NULL,NULL,'[{"id":"A","text":"$\\{-1, 0, +1\\}$"},{"id":"B","text":"$\\{0, 1, 2\\}$"},{"id":"C","text":"$\\{-2, 0, +2\\}$"},{"id":"D","text":"$\\{0\\}$ only"}]','"A"',NULL,'An AVL tree is a self-balancing binary search tree where the height difference between the left and right subtrees (Balance Factor $= \text{height}(L) - \text{height}(R)$) of every node must be in the set $\{-1, 0, +1\}$.',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','educator_admin','2026-08-26 18:24:30','2026-08-26 18:24:30','2026-08-26 18:24:30');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3130702_2023_015','GTU',1,0,NULL,'gtu_dataset_3130702_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'3130702','Data Structures',3,NULL,2,'Binary Search Trees & AVL Trees',NULL,'MCQ','What is the worst-case time complexity of searching for an element in a balanced AVL tree with $N$ nodes?',NULL,NULL,'[{"id":"A","text":"$O(1)$"},{"id":"B","text":"$O(\\log_2 N)$"},{"id":"C","text":"$O(N)$"},{"id":"D","text":"$O(N \\log_2 N)$"}]','"B"',NULL,'Because AVL trees maintain strict height balance ($h \le 1.44 \log_2 N$), the maximum path length from root to any leaf is strictly logarithmic, guaranteeing worst-case search complexity of $O(\log_2 N)$.',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','educator_admin','2026-08-26 18:24:30','2026-08-26 18:24:30','2026-08-26 18:24:30');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110005_2024_016','GTU',1,0,NULL,'gtu_dataset_3110005_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3110005','Basic Electrical Engineering',1,NULL,1,'Thevenin & Norton Theorems',NULL,'MCQ','According to Thevenin''s theorem, any linear bidirectional two-terminal DC network can be replaced by an equivalent circuit consisting of:',NULL,NULL,'[{"id":"A","text":"An open-circuit voltage source $V_{th}$ in series with an equivalent resistance $R_{th}$"},{"id":"B","text":"A short-circuit current source $I_N$ in parallel with $R_N$"},{"id":"C","text":"A variable voltage source in parallel with an inductor"},{"id":"D","text":"An ideal current source in series with a resistor"}]','"A"',NULL,'Thevenin''s Theorem states that any linear active resistive network with terminals A and B can be replaced by a single ideal voltage source $V_{th}$ (the open-circuit voltage across A-B) in series with an equivalent resistance $R_{th}$ (measured with all independent sources deactivated).',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','educator_admin','2026-08-26 18:24:30','2026-08-26 18:24:30','2026-08-26 18:24:30');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110005_2023_017','GTU',1,0,NULL,'gtu_dataset_3110005_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'3110005','Basic Electrical Engineering',1,NULL,1,'Thevenin & Norton Theorems',NULL,'MCQ','Under the Maximum Power Transfer Theorem, maximum power is delivered from a DC source with internal resistance $R_s$ to a load $R_L$ when:',NULL,NULL,'[{"id":"A","text":"$R_L = 0$"},{"id":"B","text":"$R_L = R_s$"},{"id":"C","text":"$R_L = \\infty$"},{"id":"D","text":"$R_L = 2 R_s$"}]','"B"',NULL,'Maximum power transfer in a DC circuit occurs when the load resistance equals the internal Thevenin source resistance ($R_L = R_{th} = R_s$), yielding a theoretical transfer efficiency of 50%.',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','educator_admin','2026-08-26 18:24:30','2026-08-26 18:24:30','2026-08-26 18:24:30');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2024_001','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,1,'Thin Film Interference & Newton Rings',NULL,'MCQ','In Newton''s rings experiment viewed by reflected monochromatic light of wavelength $\lambda$, the central spot is always dark because:',NULL,NULL,'[{"id":"A","text":"An additional phase change of $\\pi$ radians (path difference of $\\lambda/2$) occurs upon reflection at the rarer-to-denser medium boundary"},{"id":"B","text":"The film thickness at the point of contact is equal to $\\lambda/4$"},{"id":"C","text":"Destructive interference occurs due to absorption of light by the plano-convex lens"},{"id":"D","text":"Refraction through the glass plate introduces a path difference of $\\lambda$"}]','"A"',NULL,'According to Stokes'' treatment, when light is reflected from the boundary of a denser medium (glass plate with higher refractive index), it undergoes a phase shift of $\pi$ radians, equivalent to a path difference of $\lambda/2$. At the point of contact, film thickness $t = 0$, so the net effective path difference $\Delta = 2\mu t + \lambda/2 = \lambda/2$, which satisfies the condition for destructive interference (dark fringe).',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2024_001','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,1,'Thin Film Interference & Newton Rings',NULL,'MCQ','In Newton''s rings experiment viewed by reflected monochromatic light of wavelength $\lambda$, the central spot is always dark because:',NULL,NULL,'[{"id":"A","text":"An additional phase change of $\\pi$ radians (path difference of $\\lambda/2$) occurs upon reflection at the rarer-to-denser medium boundary"},{"id":"B","text":"The film thickness at the point of contact is equal to $\\lambda/4$"},{"id":"C","text":"Destructive interference occurs due to absorption of light by the plano-convex lens"},{"id":"D","text":"Refraction through the glass plate introduces a path difference of $\\lambda$"}]','"A"',NULL,'According to Stokes'' treatment, when light is reflected from the boundary of a denser medium (glass plate with higher refractive index), it undergoes a phase shift of $\pi$ radians, equivalent to a path difference of $\lambda/2$. At the point of contact, film thickness $t = 0$, so the net effective path difference $\Delta = 2\mu t + \lambda/2 = \lambda/2$, which satisfies the condition for destructive interference (dark fringe).',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2023_002','GTU',1,0,NULL,'gtu_physics_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,1,'Thin Film Interference & Newton Rings',NULL,'MCQ','In Newton''s rings experiment using light of wavelength $\lambda$, the diameter $D_n$ of the $n^{\text{th}}$ dark ring in reflected light is directly proportional to:',NULL,NULL,'[{"id":"A","text":"$\\sqrt{n}$"},{"id":"B","text":"$n$"},{"id":"C","text":"$n^2$"},{"id":"D","text":"$\\sqrt{2n - 1}$"}]','"A"',NULL,'The diameter of the $n^{\text{th}}$ dark ring in reflected light is given by $D_n = \sqrt{4 n R \lambda} = 2\sqrt{n R \lambda}$, where $R$ is the radius of curvature of the plano-convex lens. Therefore, $D_n \propto \sqrt{n}$ (proportional to the square root of natural numbers). For bright rings, diameter is proportional to $\sqrt{2n - 1}$.',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2023_002','GTU',1,0,NULL,'gtu_physics_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,1,'Thin Film Interference & Newton Rings',NULL,'MCQ','In Newton''s rings experiment using light of wavelength $\lambda$, the diameter $D_n$ of the $n^{\text{th}}$ dark ring in reflected light is directly proportional to:',NULL,NULL,'[{"id":"A","text":"$\\sqrt{n}$"},{"id":"B","text":"$n$"},{"id":"C","text":"$n^2$"},{"id":"D","text":"$\\sqrt{2n - 1}$"}]','"A"',NULL,'The diameter of the $n^{\text{th}}$ dark ring in reflected light is given by $D_n = \sqrt{4 n R \lambda} = 2\sqrt{n R \lambda}$, where $R$ is the radius of curvature of the plano-convex lens. Therefore, $D_n \propto \sqrt{n}$ (proportional to the square root of natural numbers). For bright rings, diameter is proportional to $\sqrt{2n - 1}$.',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2024_003','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,1,'Diffraction Grating & Resolving Power',NULL,'MCQ','A plane transmission diffraction grating has $N$ lines per centimeter. What is the maximum wavelength of light $\lambda$ for which the first-order principal maximum ($n=1$) can be observed at normal incidence?',NULL,NULL,'[{"id":"A","text":"$\\lambda_{\\text{max}} = \\frac{1}{N}$"},{"id":"B","text":"$\\lambda_{\\text{max}} = \\frac{1}{2N}$"},{"id":"C","text":"$\\lambda_{\\text{max}} = N$"},{"id":"D","text":"$\\lambda_{\\text{max}} = \\frac{2}{N}$"}]','"A"',NULL,'The grating equation at normal incidence is $(a + b)\sin\theta = n\lambda$, where the grating element $(a + b) = 1/N$. For the first order ($n=1$), $\lambda = \frac{1}{N}\sin\theta$. Since the maximum possible value of $\sin\theta$ is 1 (at $\theta = 90^\circ$), the maximum observable wavelength is $\lambda_{\text{max}} = 1/N$.',NULL,NULL,0,NULL,1,0.25,'medium','APPLY',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2024_003','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,1,'Diffraction Grating & Resolving Power',NULL,'MCQ','A plane transmission diffraction grating has $N$ lines per centimeter. What is the maximum wavelength of light $\lambda$ for which the first-order principal maximum ($n=1$) can be observed at normal incidence?',NULL,NULL,'[{"id":"A","text":"$\\lambda_{\\text{max}} = \\frac{1}{N}$"},{"id":"B","text":"$\\lambda_{\\text{max}} = \\frac{1}{2N}$"},{"id":"C","text":"$\\lambda_{\\text{max}} = N$"},{"id":"D","text":"$\\lambda_{\\text{max}} = \\frac{2}{N}$"}]','"A"',NULL,'The grating equation at normal incidence is $(a + b)\sin\theta = n\lambda$, where the grating element $(a + b) = 1/N$. For the first order ($n=1$), $\lambda = \frac{1}{N}\sin\theta$. Since the maximum possible value of $\sin\theta$ is 1 (at $\theta = 90^\circ$), the maximum observable wavelength is $\lambda_{\text{max}} = 1/N$.',NULL,NULL,0,NULL,1,0.25,'medium','APPLY',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2024_004','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,1,'Wedge Shaped Thin Film',NULL,'MCQ','In an air wedge film illuminated by sodium light of wavelength $\lambda = 6000\text{ \AA}$, consecutive dark fringes are separated by fringe width $\beta = 0.12\text{ mm}$. What is the wedge angle $\theta$ in radians?',NULL,NULL,'[{"id":"A","text":"$2.5 \\times 10^{-3}\\text{ rad}$"},{"id":"B","text":"$5.0 \\times 10^{-3}\\text{ rad}$"},{"id":"C","text":"$1.25 \\times 10^{-3}\\text{ rad}$"},{"id":"D","text":"$2.5 \\times 10^{-4}\\text{ rad}$"}]','"A"',NULL,'Fringe width in a wedge-shaped film is given by $\beta = \frac{\lambda}{2\mu \theta}$. For an air wedge ($\mu = 1$), $\theta = \frac{\lambda}{2\beta} = \frac{6000 \times 10^{-10}\text{ m}}{2 \times (0.12 \times 10^{-3}\text{ m})} = \frac{6 \times 10^{-7}}{2.4 \times 10^{-4}} = 2.5 \times 10^{-3}\text{ radians}$.',NULL,NULL,0,NULL,1,0.25,'medium','APPLY',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2024_004','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,1,'Wedge Shaped Thin Film',NULL,'MCQ','In an air wedge film illuminated by sodium light of wavelength $\lambda = 6000\text{ \AA}$, consecutive dark fringes are separated by fringe width $\beta = 0.12\text{ mm}$. What is the wedge angle $\theta$ in radians?',NULL,NULL,'[{"id":"A","text":"$2.5 \\times 10^{-3}\\text{ rad}$"},{"id":"B","text":"$5.0 \\times 10^{-3}\\text{ rad}$"},{"id":"C","text":"$1.25 \\times 10^{-3}\\text{ rad}$"},{"id":"D","text":"$2.5 \\times 10^{-4}\\text{ rad}$"}]','"A"',NULL,'Fringe width in a wedge-shaped film is given by $\beta = \frac{\lambda}{2\mu \theta}$. For an air wedge ($\mu = 1$), $\theta = \frac{\lambda}{2\beta} = \frac{6000 \times 10^{-10}\text{ m}}{2 \times (0.12 \times 10^{-3}\text{ m})} = \frac{6 \times 10^{-7}}{2.4 \times 10^{-4}} = 2.5 \times 10^{-3}\text{ radians}$.',NULL,NULL,0,NULL,1,0.25,'medium','APPLY',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2023_005','GTU',1,0,NULL,'gtu_physics_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,1,'Fraunhofer Single Slit Diffraction',NULL,'MCQ','In Fraunhofer diffraction at a single slit of width $a$ illuminated by light of wavelength $\lambda$, the condition for the $m^{\text{th}}$ minima is:',NULL,NULL,'[{"id":"A","text":"$a \\sin\\theta = m\\lambda \\quad (m = \\pm 1, \\pm 2, \\dots)$"},{"id":"B","text":"$a \\sin\\theta = (2m+1)\\frac{\\lambda}{2}$"},{"id":"C","text":"$a \\cos\\theta = m\\lambda$"},{"id":"D","text":"$a \\tan\\theta = m\\lambda$"}]','"A"',NULL,'For Fraunhofer single slit diffraction, the path difference between secondary wavelets from the top and bottom edges of the slit is $a \sin\theta$. When $a \sin\theta = m\lambda$ with $m \in \{\pm 1, \pm 2, \dots\}$, the slit can be divided into $2m$ equal zones whose wavelets cancel in pairs, producing complete destructive interference (minima).',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2023_005','GTU',1,0,NULL,'gtu_physics_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,1,'Fraunhofer Single Slit Diffraction',NULL,'MCQ','In Fraunhofer diffraction at a single slit of width $a$ illuminated by light of wavelength $\lambda$, the condition for the $m^{\text{th}}$ minima is:',NULL,NULL,'[{"id":"A","text":"$a \\sin\\theta = m\\lambda \\quad (m = \\pm 1, \\pm 2, \\dots)$"},{"id":"B","text":"$a \\sin\\theta = (2m+1)\\frac{\\lambda}{2}$"},{"id":"C","text":"$a \\cos\\theta = m\\lambda$"},{"id":"D","text":"$a \\tan\\theta = m\\lambda$"}]','"A"',NULL,'For Fraunhofer single slit diffraction, the path difference between secondary wavelets from the top and bottom edges of the slit is $a \sin\theta$. When $a \sin\theta = m\lambda$ with $m \in \{\pm 1, \pm 2, \dots\}$, the slit can be divided into $2m$ equal zones whose wavelets cancel in pairs, producing complete destructive interference (minima).',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2024_006','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,2,'Einstein Coefficients & Population Inversion',NULL,'MCQ','What is the physical relationship between Einstein''s coefficient of spontaneous emission $A_{21}$ and stimulated emission $B_{21}$ in a two-level atomic system?',NULL,NULL,'[{"id":"A","text":"$\\frac{A_{21}}{B_{21}} = \\frac{8\\pi h \\nu^3}{c^3}$"},{"id":"B","text":"$\\frac{A_{21}}{B_{21}} = \\frac{8\\pi h \\nu^2}{c^2}$"},{"id":"C","text":"$\\frac{A_{21}}{B_{21}} = \\frac{h \\nu}{k T}$"},{"id":"D","text":"$\\frac{A_{21}}{B_{21}} = 1$"}]','"A"',NULL,'By equating the rate of upward and downward transitions under thermal equilibrium and comparing with Planck''s blackbody radiation formula, Einstein derived the ratio $\frac{A_{21}}{B_{21}} = \frac{8\pi h \nu^3}{c^3}$. This demonstrates that spontaneous emission increases rapidly with frequency $\nu^3$, making X-ray lasers much harder to construct than optical lasers.',NULL,NULL,0,NULL,1,0.25,'medium','UNDERSTAND',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2024_006','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,2,'Einstein Coefficients & Population Inversion',NULL,'MCQ','What is the physical relationship between Einstein''s coefficient of spontaneous emission $A_{21}$ and stimulated emission $B_{21}$ in a two-level atomic system?',NULL,NULL,'[{"id":"A","text":"$\\frac{A_{21}}{B_{21}} = \\frac{8\\pi h \\nu^3}{c^3}$"},{"id":"B","text":"$\\frac{A_{21}}{B_{21}} = \\frac{8\\pi h \\nu^2}{c^2}$"},{"id":"C","text":"$\\frac{A_{21}}{B_{21}} = \\frac{h \\nu}{k T}$"},{"id":"D","text":"$\\frac{A_{21}}{B_{21}} = 1$"}]','"A"',NULL,'By equating the rate of upward and downward transitions under thermal equilibrium and comparing with Planck''s blackbody radiation formula, Einstein derived the ratio $\frac{A_{21}}{B_{21}} = \frac{8\pi h \nu^3}{c^3}$. This demonstrates that spontaneous emission increases rapidly with frequency $\nu^3$, making X-ray lasers much harder to construct than optical lasers.',NULL,NULL,0,NULL,1,0.25,'medium','UNDERSTAND',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2023_007','GTU',1,0,NULL,'gtu_physics_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,2,'He-Ne Laser Mechanism',NULL,'MCQ','In a Helium-Neon (He-Ne) continuous gas laser, what is the primary function of the Helium atoms in the gas mixture?',NULL,NULL,'[{"id":"A","text":"To achieve efficient resonant collision energy transfer to excite Neon atoms to metastable states ($2s$ and $3s$)"},{"id":"B","text":"To emit the characteristic $632.8\\text{ nm}$ red laser photon directly"},{"id":"C","text":"To act as the optical cavity resonant reflector mirror"},{"id":"D","text":"To cool down the discharge tube by absorbing heat photons"}]','"A"',NULL,'In a He-Ne laser (ratio roughly 10:1), electric discharge excites He atoms from ground state to metastable $2^3S$ and $2^1S$ states by electron impact. Because these He energy levels almost exactly match the $2s$ and $3s$ levels of Neon, Helium atoms transfer energy to Neon atoms via resonant inelastic collisions, establishing the population inversion in Neon.',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2023_007','GTU',1,0,NULL,'gtu_physics_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,2,'He-Ne Laser Mechanism',NULL,'MCQ','In a Helium-Neon (He-Ne) continuous gas laser, what is the primary function of the Helium atoms in the gas mixture?',NULL,NULL,'[{"id":"A","text":"To achieve efficient resonant collision energy transfer to excite Neon atoms to metastable states ($2s$ and $3s$)"},{"id":"B","text":"To emit the characteristic $632.8\\text{ nm}$ red laser photon directly"},{"id":"C","text":"To act as the optical cavity resonant reflector mirror"},{"id":"D","text":"To cool down the discharge tube by absorbing heat photons"}]','"A"',NULL,'In a He-Ne laser (ratio roughly 10:1), electric discharge excites He atoms from ground state to metastable $2^3S$ and $2^1S$ states by electron impact. Because these He energy levels almost exactly match the $2s$ and $3s$ levels of Neon, Helium atoms transfer energy to Neon atoms via resonant inelastic collisions, establishing the population inversion in Neon.',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2024_008','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,2,'Optical Fibers & Numerical Aperture',NULL,'MCQ','An optical fiber has a core refractive index $n_1 = 1.50$ and a cladding refractive index $n_2 = 1.45$. What is its Numerical Aperture ($NA$) in air ($n_0 = 1.0$)?',NULL,NULL,'[{"id":"A","text":"$0.384$"},{"id":"B","text":"$0.050$"},{"id":"C","text":"$0.707$"},{"id":"D","text":"$0.125$"}]','"A"',NULL,'The Numerical Aperture represents the light-gathering capacity of the fiber and is given by $NA = \sqrt{n_1^2 - n_2^2} = \sqrt{(1.50)^2 - (1.45)^2} = \sqrt{2.25 - 2.1025} = \sqrt{0.1475} \approx 0.384$.',NULL,NULL,0,NULL,1,0.25,'medium','APPLY',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2024_008','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,2,'Optical Fibers & Numerical Aperture',NULL,'MCQ','An optical fiber has a core refractive index $n_1 = 1.50$ and a cladding refractive index $n_2 = 1.45$. What is its Numerical Aperture ($NA$) in air ($n_0 = 1.0$)?',NULL,NULL,'[{"id":"A","text":"$0.384$"},{"id":"B","text":"$0.050$"},{"id":"C","text":"$0.707$"},{"id":"D","text":"$0.125$"}]','"A"',NULL,'The Numerical Aperture represents the light-gathering capacity of the fiber and is given by $NA = \sqrt{n_1^2 - n_2^2} = \sqrt{(1.50)^2 - (1.45)^2} = \sqrt{2.25 - 2.1025} = \sqrt{0.1475} \approx 0.384$.',NULL,NULL,0,NULL,1,0.25,'medium','APPLY',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2024_009','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,2,'Optical Fiber Acceptance Angle & V-Number',NULL,'MCQ','For light to propagate successfully through a step-index optical fiber via Total Internal Reflection (TIR), the angle of incidence $\theta_i$ at the fiber air-core interface must satisfy:',NULL,NULL,'[{"id":"A","text":"$\\theta_i \\le \\theta_a = \\sin^{-1}(NA)$"},{"id":"B","text":"$\\theta_i > \\sin^{-1}(NA)$"},{"id":"C","text":"$\\theta_i = 90^\\circ$"},{"id":"D","text":"$\\theta_i = \\sin^{-1}(n_2 / n_1)$"}]','"A"',NULL,'The maximum launch angle at which light enters the fiber and still undergoes TIR at the core-cladding boundary is the acceptance angle $\theta_a = \sin^{-1}(NA)$. Any ray launched with $\theta_i \le \theta_a$ will strike the core-cladding interface at an angle greater than the critical angle $\theta_c$, ensuring lossless guided propagation.',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
