INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2023_010','GTU',1,0,NULL,'gtu_physics_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,2,'Optical Fiber Types',NULL,'MCQ','Which optical fiber design is specifically engineered to minimize intermodal dispersion over long-distance high-bandwidth telecommunications?',NULL,NULL,'[{"id":"A","text":"Graded-Index (GRIN) Multimode Fiber"},{"id":"B","text":"Step-Index Multimode Fiber with large core diameter"},{"id":"C","text":"Plastic Step-Index Optical Fiber"},{"id":"D","text":"Unclad Glass Rod"}]','"A"',NULL,'In Graded-Index (GRIN) fibers, the refractive index decreases parabolically from the core center towards the cladding. Light rays traveling along longer outer helical paths travel faster through the lower index medium than axial rays, equalizing transit times and dramatically reducing intermodal dispersion.',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2023_010','GTU',1,0,NULL,'gtu_physics_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,2,'Optical Fiber Types',NULL,'MCQ','Which optical fiber design is specifically engineered to minimize intermodal dispersion over long-distance high-bandwidth telecommunications?',NULL,NULL,'[{"id":"A","text":"Graded-Index (GRIN) Multimode Fiber"},{"id":"B","text":"Step-Index Multimode Fiber with large core diameter"},{"id":"C","text":"Plastic Step-Index Optical Fiber"},{"id":"D","text":"Unclad Glass Rod"}]','"A"',NULL,'In Graded-Index (GRIN) fibers, the refractive index decreases parabolically from the core center towards the cladding. Light rays traveling along longer outer helical paths travel faster through the lower index medium than axial rays, equalizing transit times and dramatically reducing intermodal dispersion.',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2024_011','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,3,'De Broglie Wavelength & Matter Waves',NULL,'MCQ','An electron of mass $m$ and charge $e$ is accelerated from rest through a potential difference of $V = 100\text{ Volts}$. What is its de Broglie wavelength $\lambda$?',NULL,NULL,'[{"id":"A","text":"$1.227\\text{ \\AA} \\quad (0.1227\\text{ nm})$"},{"id":"B","text":"$12.27\\text{ \\AA}$"},{"id":"C","text":"$0.01227\\text{ nm}$"},{"id":"D","text":"$6.626\\text{ \\AA}$"}]','"A"',NULL,'For a non-relativistic electron accelerated across potential $V$, $\lambda = \frac{h}{p} = \frac{h}{\sqrt{2m e V}} = \frac{12.27}{\sqrt{V}}\text{ \AA}$. For $V = 100\text{ V}$, $\lambda = \frac{12.27}{\sqrt{100}} = \frac{12.27}{10} = 1.227\text{ \AA} = 0.1227\text{ nm}$.',NULL,NULL,0,NULL,1,0.25,'medium','APPLY',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
