INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2024_012','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,3,'Heisenberg Uncertainty Principle',NULL,'MCQ','Heisenberg''s Uncertainty Principle asserts that for any quantum particle, the simultaneous measurement of position $x$ and linear momentum $p_x$ is fundamentally constrained by:',NULL,NULL,'[{"id":"A","text":"$\\Delta x \\cdot \\Delta p_x \\ge \\frac{\\hbar}{2} = \\frac{h}{4\\pi}$"},{"id":"B","text":"$\\Delta x \\cdot \\Delta p_x \\le \\frac{h}{2\\pi}$"},{"id":"C","text":"$\\Delta x \\cdot \\Delta p_x = 0$"},{"id":"D","text":"$\\Delta x \\cdot \\Delta p_x \\ge h c$"}]','"A"',NULL,'Heisenberg showed that the wave nature of matter imposes a fundamental quantum limit on the product of uncertainties in conjugate variables: $\Delta x \cdot \Delta p_x \ge \frac{\hbar}{2} = \frac{h}{4\pi}$. Similarly, energy and time satisfy $\Delta E \cdot \Delta t \ge \frac{\hbar}{2}$.',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2024_012','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,3,'Heisenberg Uncertainty Principle',NULL,'MCQ','Heisenberg''s Uncertainty Principle asserts that for any quantum particle, the simultaneous measurement of position $x$ and linear momentum $p_x$ is fundamentally constrained by:',NULL,NULL,'[{"id":"A","text":"$\\Delta x \\cdot \\Delta p_x \\ge \\frac{\\hbar}{2} = \\frac{h}{4\\pi}$"},{"id":"B","text":"$\\Delta x \\cdot \\Delta p_x \\le \\frac{h}{2\\pi}$"},{"id":"C","text":"$\\Delta x \\cdot \\Delta p_x = 0$"},{"id":"D","text":"$\\Delta x \\cdot \\Delta p_x \\ge h c$"}]','"A"',NULL,'Heisenberg showed that the wave nature of matter imposes a fundamental quantum limit on the product of uncertainties in conjugate variables: $\Delta x \cdot \Delta p_x \ge \frac{\hbar}{2} = \frac{h}{4\pi}$. Similarly, energy and time satisfy $\Delta E \cdot \Delta t \ge \frac{\hbar}{2}$.',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2023_013','GTU',1,0,NULL,'gtu_physics_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,3,'Particle in a 1D Infinite Potential Box',NULL,'MCQ','A quantum particle of mass $m$ is trapped in a 1D rigid box of length $L$ with infinite potential walls ($0 \le x \le L$). What is the energy of its second excited state ($n=3$)?',NULL,NULL,'[{"id":"A","text":"$E_3 = \\frac{9 h^2}{8 m L^2}$"},{"id":"B","text":"$E_3 = \\frac{4 h^2}{8 m L^2}$"},{"id":"C","text":"$E_3 = \\frac{3 h^2}{8 m L^2}$"},{"id":"D","text":"$E_3 = \\frac{16 h^2}{8 m L^2}$"}]','"A"',NULL,'Energy eigenvalues for a particle in a 1D infinite square well are $E_n = \frac{n^2 h^2}{8 m L^2} = \frac{n^2 \pi^2 \hbar^2}{2 m L^2}$. The ground state corresponds to $n=1$, the first excited state to $n=2$, and the second excited state to $n=3$. Thus, $E_3 = \frac{3^2 h^2}{8 m L^2} = \frac{9 h^2}{8 m L^2}$.',NULL,NULL,0,NULL,1,0.25,'medium','APPLY',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
