INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2024_014','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,3,'Born Interpretation of Wavefunction',NULL,'MCQ','According to Max Born''s probabilistic interpretation, what is the physical meaning of $|\psi(x, t)|^2 dV = \psi^*(x,t)\psi(x,t) dV$?',NULL,NULL,'[{"id":"A","text":"The probability of finding the particle within volume element $dV$ at time $t$"},{"id":"B","text":"The exact velocity of the particle at position $x$"},{"id":"C","text":"The charge density distribution divided by $c$"},{"id":"D","text":"The instantaneous kinetic energy of the wave packet"}]','"A"',NULL,'While the complex wavefunction $\psi(x,t)$ itself is not directly measurable, its squared modulus $|\psi(x,t)|^2 = \psi^*(x,t)\psi(x,t)$ represents the probability density $P(x,t)$. Multiplying by volume element $dV$ gives the probability of locating the particle in that region.',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2024_014','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,3,'Born Interpretation of Wavefunction',NULL,'MCQ','According to Max Born''s probabilistic interpretation, what is the physical meaning of $|\psi(x, t)|^2 dV = \psi^*(x,t)\psi(x,t) dV$?',NULL,NULL,'[{"id":"A","text":"The probability of finding the particle within volume element $dV$ at time $t$"},{"id":"B","text":"The exact velocity of the particle at position $x$"},{"id":"C","text":"The charge density distribution divided by $c$"},{"id":"D","text":"The instantaneous kinetic energy of the wave packet"}]','"A"',NULL,'While the complex wavefunction $\psi(x,t)$ itself is not directly measurable, its squared modulus $|\psi(x,t)|^2 = \psi^*(x,t)\psi(x,t)$ represents the probability density $P(x,t)$. Multiplying by volume element $dV$ gives the probability of locating the particle in that region.',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2024_015','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,3,'Wavefunction Normalization',NULL,'MCQ','The normalized wave function of a particle in a 1D box of width $L$ is $\psi_n(x) = \sqrt{\frac{2}{L}}\sin\left(\frac{n\pi x}{L}\right)$. What is the probability of finding the particle in the ground state ($n=1$) in the left half of the box ($0 \le x \le L/2$)?',NULL,NULL,'[{"id":"A","text":"$0.50$ ($50\\%$)"},{"id":"B","text":"$0.25$ ($25\\%$)"},{"id":"C","text":"$0.75$ ($75\\%$)"},{"id":"D","text":"$1.00$ ($100\\%$)"}]','"A"',NULL,'The probability density $|\psi_1(x)|^2 = \frac{2}{L}\sin^2\left(\frac{\pi x}{L}\right)$ is symmetric about the center of the box $x = L/2$. Integrating from $0$ to $L/2$ yields $\int_0^{L/2} \frac{2}{L}\sin^2\left(\frac{\pi x}{L}\right) dx = \frac{1}{2} = 0.50$.',NULL,NULL,0,NULL,1,0.25,'medium','APPLY',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2024_015','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,3,'Wavefunction Normalization',NULL,'MCQ','The normalized wave function of a particle in a 1D box of width $L$ is $\psi_n(x) = \sqrt{\frac{2}{L}}\sin\left(\frac{n\pi x}{L}\right)$. What is the probability of finding the particle in the ground state ($n=1$) in the left half of the box ($0 \le x \le L/2$)?',NULL,NULL,'[{"id":"A","text":"$0.50$ ($50\\%$)"},{"id":"B","text":"$0.25$ ($25\\%$)"},{"id":"C","text":"$0.75$ ($75\\%$)"},{"id":"D","text":"$1.00$ ($100\\%$)"}]','"A"',NULL,'The probability density $|\psi_1(x)|^2 = \frac{2}{L}\sin^2\left(\frac{\pi x}{L}\right)$ is symmetric about the center of the box $x = L/2$. Integrating from $0$ to $L/2$ yields $\int_0^{L/2} \frac{2}{L}\sin^2\left(\frac{\pi x}{L}\right) dx = \frac{1}{2} = 0.50$.',NULL,NULL,0,NULL,1,0.25,'medium','APPLY',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2024_016','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,4,'Meissner Effect & Diamagnetism',NULL,'MCQ','When a material transitions into the superconducting state below its critical temperature $T_c$ in the presence of an external magnetic field $B$, it expels all magnetic flux from its interior ($B=0$). This phenomenon is called the:',NULL,NULL,'[{"id":"A","text":"Meissner Effect"},{"id":"B","text":"Hall Effect"},{"id":"C","text":"Seebeck Effect"},{"id":"D","text":"Peltier Effect"}]','"A"',NULL,'Discovered by Walther Meissner and Robert Ochsenfeld (1933), the Meissner effect shows that superconductors exhibit perfect diamagnetism with magnetic susceptibility $\chi_m = -1$ and relative permeability $\mu_r = 0$, completely expelling magnetic flux lines from their bulk interior.',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2024_016','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,4,'Meissner Effect & Diamagnetism',NULL,'MCQ','When a material transitions into the superconducting state below its critical temperature $T_c$ in the presence of an external magnetic field $B$, it expels all magnetic flux from its interior ($B=0$). This phenomenon is called the:',NULL,NULL,'[{"id":"A","text":"Meissner Effect"},{"id":"B","text":"Hall Effect"},{"id":"C","text":"Seebeck Effect"},{"id":"D","text":"Peltier Effect"}]','"A"',NULL,'Discovered by Walther Meissner and Robert Ochsenfeld (1933), the Meissner effect shows that superconductors exhibit perfect diamagnetism with magnetic susceptibility $\chi_m = -1$ and relative permeability $\mu_r = 0$, completely expelling magnetic flux lines from their bulk interior.',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2023_017','GTU',1,0,NULL,'gtu_physics_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,4,'Critical Magnetic Field',NULL,'MCQ','A superconductor has a critical field $H_0 = 8 \times 10^4\text{ A/m}$ at $T = 0\text{ K}$ and critical temperature $T_c = 8\text{ K}$. What is its critical magnetic field $H_c$ at $T = 4\text{ K}$?',NULL,NULL,'[{"id":"A","text":"$6.0 \\times 10^4\\text{ A/m}$"},{"id":"B","text":"$4.0 \\times 10^4\\text{ A/m}$"},{"id":"C","text":"$2.0 \\times 10^4\\text{ A/m}$"},{"id":"D","text":"$7.5 \\times 10^4\\text{ A/m}$"}]','"A"',NULL,'The critical field variation with temperature is given by $H_c(T) = H_0 \left[1 - \left(\frac{T}{T_c}\right)^2\right] = 8 \times 10^4 \left[1 - \left(\frac{4}{8}\right)^2\right] = 8 \times 10^4 \left[1 - \frac{1}{4}\right] = 8 \times 10^4 \times 0.75 = 6.0 \times 10^4\text{ A/m}$.',NULL,NULL,0,NULL,1,0.25,'medium','APPLY',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2023_017','GTU',1,0,NULL,'gtu_physics_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,4,'Critical Magnetic Field',NULL,'MCQ','A superconductor has a critical field $H_0 = 8 \times 10^4\text{ A/m}$ at $T = 0\text{ K}$ and critical temperature $T_c = 8\text{ K}$. What is its critical magnetic field $H_c$ at $T = 4\text{ K}$?',NULL,NULL,'[{"id":"A","text":"$6.0 \\times 10^4\\text{ A/m}$"},{"id":"B","text":"$4.0 \\times 10^4\\text{ A/m}$"},{"id":"C","text":"$2.0 \\times 10^4\\text{ A/m}$"},{"id":"D","text":"$7.5 \\times 10^4\\text{ A/m}$"}]','"A"',NULL,'The critical field variation with temperature is given by $H_c(T) = H_0 \left[1 - \left(\frac{T}{T_c}\right)^2\right] = 8 \times 10^4 \left[1 - \left(\frac{4}{8}\right)^2\right] = 8 \times 10^4 \left[1 - \frac{1}{4}\right] = 8 \times 10^4 \times 0.75 = 6.0 \times 10^4\text{ A/m}$.',NULL,NULL,0,NULL,1,0.25,'medium','APPLY',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2024_018','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,4,'BCS Theory & Cooper Pairs',NULL,'MCQ','According to the BCS (Bardeen-Cooper-Schrieffer) microscopic theory of superconductivity, electrical resistance vanishes due to the formation of:',NULL,NULL,'[{"id":"A","text":"Cooper pairs formed via electron-phonon-electron lattice interactions"},{"id":"B","text":"Positron-electron annihilation pairs"},{"id":"C","text":"Hole-hole repulsive clusters"},{"id":"D","text":"Photon-electron condensates"}]','"A"',NULL,'In BCS theory, an electron passing through the crystal lattice attracts positive ions, creating a slight local polarization (phonon excitation). A second electron is attracted to this positive region, forming a bound electron-electron pair called a Cooper pair with zero net spin (boson behavior) that moves without lattice scattering.',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2024_018','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,4,'BCS Theory & Cooper Pairs',NULL,'MCQ','According to the BCS (Bardeen-Cooper-Schrieffer) microscopic theory of superconductivity, electrical resistance vanishes due to the formation of:',NULL,NULL,'[{"id":"A","text":"Cooper pairs formed via electron-phonon-electron lattice interactions"},{"id":"B","text":"Positron-electron annihilation pairs"},{"id":"C","text":"Hole-hole repulsive clusters"},{"id":"D","text":"Photon-electron condensates"}]','"A"',NULL,'In BCS theory, an electron passing through the crystal lattice attracts positive ions, creating a slight local polarization (phonon excitation). A second electron is attracted to this positive region, forming a bound electron-electron pair called a Cooper pair with zero net spin (boson behavior) that moves without lattice scattering.',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2024_019','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,4,'Magnetic Materials & Hysteresis Loop',NULL,'MCQ','In a ferromagnetic material $B\text{-}H$ hysteresis loop, the value of magnetic induction $B$ remaining in the specimen when the magnetizing field $H$ is reduced to zero is called:',NULL,NULL,'[{"id":"A","text":"Retentivity (Residual Magnetism)"},{"id":"B","text":"Coercivity"},{"id":"C","text":"Curie Temperature"},{"id":"D","text":"Permeability"}]','"A"',NULL,'Retentivity (or remanence) is the residual flux density $B_r$ remaining in a ferromagnetic material after the external magnetizing force $H$ has been reduced to zero. Coercivity $H_c$, on the other hand, is the reverse magnetic field required to reduce this residual magnetism back to zero.',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
