INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2023_020','GTU',1,0,NULL,'gtu_physics_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,4,'Soft vs Hard Magnetic Materials',NULL,'MCQ','Which property is characteristic of a Soft Magnetic Material (e.g., Silicon Steel, Permalloy) used in transformer cores?',NULL,NULL,'[{"id":"A","text":"Narrow hysteresis loop, low coercivity, and low hysteresis energy loss"},{"id":"B","text":"Broad hysteresis loop, high coercivity, and high retentivity"},{"id":"C","text":"Negative magnetic susceptibility independent of temperature"},{"id":"D","text":"Zero electrical resistivity at room temperature"}]','"A"',NULL,'Soft magnetic materials can be easily magnetized and demagnetized. They have high permeability, small coercive force, and narrow hysteresis loops, which minimizes the area enclosed by the loop and thus drastically reduces core heating/energy loss in AC transformer cores and electric motor armatures.',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
