INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2024_021','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,5,'Quantum Confinement & Dimensionality',NULL,'MCQ','A Quantum Dot is classified as a zero-dimensional (0D) nanomaterial because:',NULL,NULL,'[{"id":"A","text":"Quantum confinement of charge carriers occurs along all three spatial dimensions ($x, y, z < 100\\text{ nm}$)"},{"id":"B","text":"Electrons can move freely along two spatial directions"},{"id":"C","text":"It has zero mass and zero volume"},{"id":"D","text":"It possesses infinite electrical conductivity"}]','"A"',NULL,'In nanomaterials, dimensionality is defined by the degrees of freedom for electron motion: 2D nanostructures (Quantum Wells) confine electrons in 1 dimension, 1D nanostructures (Quantum Wires/Nanotubes) confine in 2 dimensions, and 0D nanostructures (Quantum Dots/Nanoparticles) confine electrons in all 3 spatial dimensions ($< 100\text{ nm}$), producing discrete atomic-like energy levels.',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2024_021','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,5,'Quantum Confinement & Dimensionality',NULL,'MCQ','A Quantum Dot is classified as a zero-dimensional (0D) nanomaterial because:',NULL,NULL,'[{"id":"A","text":"Quantum confinement of charge carriers occurs along all three spatial dimensions ($x, y, z < 100\\text{ nm}$)"},{"id":"B","text":"Electrons can move freely along two spatial directions"},{"id":"C","text":"It has zero mass and zero volume"},{"id":"D","text":"It possesses infinite electrical conductivity"}]','"A"',NULL,'In nanomaterials, dimensionality is defined by the degrees of freedom for electron motion: 2D nanostructures (Quantum Wells) confine electrons in 1 dimension, 1D nanostructures (Quantum Wires/Nanotubes) confine in 2 dimensions, and 0D nanostructures (Quantum Dots/Nanoparticles) confine electrons in all 3 spatial dimensions ($< 100\text{ nm}$), producing discrete atomic-like energy levels.',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2024_022','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,5,'Surface-to-Volume Ratio & Melting Point',NULL,'MCQ','When a bulk material of radius $R$ is pulverized into nanoscale particles of radius $r$ ($r \ll R$), what happens to its surface-to-volume ratio ($S/V$) and melting point?',NULL,NULL,'[{"id":"A","text":"Surface-to-volume ratio increases drastically, causing a significant reduction in melting point"},{"id":"B","text":"Surface-to-volume ratio decreases, increasing the melting point"},{"id":"C","text":"Both surface-to-volume ratio and melting point remain strictly constant"},{"id":"D","text":"Surface-to-volume ratio drops to zero"}]','"A"',NULL,'For spherical particles, surface-to-volume ratio $S/V = \frac{4\pi r^2}{(4/3)\pi r^3} = \frac{3}{r}$, which increases dramatically as particle radius $r$ shrinks into the nanoscale ($1\text{--}100\text{ nm}$). Because a larger fraction of atoms reside on the surface with unsaturated dangling bonds and higher surface energy, the melting point of nanoparticles decreases compared to bulk.',NULL,NULL,0,NULL,1,0.25,'medium','ANALYZE',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2024_022','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,5,'Surface-to-Volume Ratio & Melting Point',NULL,'MCQ','When a bulk material of radius $R$ is pulverized into nanoscale particles of radius $r$ ($r \ll R$), what happens to its surface-to-volume ratio ($S/V$) and melting point?',NULL,NULL,'[{"id":"A","text":"Surface-to-volume ratio increases drastically, causing a significant reduction in melting point"},{"id":"B","text":"Surface-to-volume ratio decreases, increasing the melting point"},{"id":"C","text":"Both surface-to-volume ratio and melting point remain strictly constant"},{"id":"D","text":"Surface-to-volume ratio drops to zero"}]','"A"',NULL,'For spherical particles, surface-to-volume ratio $S/V = \frac{4\pi r^2}{(4/3)\pi r^3} = \frac{3}{r}$, which increases dramatically as particle radius $r$ shrinks into the nanoscale ($1\text{--}100\text{ nm}$). Because a larger fraction of atoms reside on the surface with unsaturated dangling bonds and higher surface energy, the melting point of nanoparticles decreases compared to bulk.',NULL,NULL,0,NULL,1,0.25,'medium','ANALYZE',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2023_023','GTU',1,0,NULL,'gtu_physics_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,5,'Carbon Nanotubes (CNTs)',NULL,'MCQ','Single-Walled Carbon Nanotubes (SWCNTs) can be conceptually described as a rolled-up cylindrical sheet of:',NULL,NULL,'[{"id":"A","text":"Graphene ($sp^2$-hybridized honeycomb hexagonal carbon lattice)"},{"id":"B","text":"Diamond ($sp^3$-hybridized tetrahedral crystal lattice)"},{"id":"C","text":"Fullerene ($C_{60}$ soccer-ball molecule)"},{"id":"D","text":"Amorphous carbon soot"}]','"A"',NULL,'A single-walled carbon nanotube (SWCNT) is formed by rolling a single two-dimensional monolayer sheet of graphene (consisting of $sp^2$-hybridized carbon atoms arranged in a 2D honeycomb lattice) into a seamless cylinder with diameters typically between $0.8\text{--}2.0\text{ nm}$.',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2023_023','GTU',1,0,NULL,'gtu_physics_2023',NULL,'GTU',2023,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,5,'Carbon Nanotubes (CNTs)',NULL,'MCQ','Single-Walled Carbon Nanotubes (SWCNTs) can be conceptually described as a rolled-up cylindrical sheet of:',NULL,NULL,'[{"id":"A","text":"Graphene ($sp^2$-hybridized honeycomb hexagonal carbon lattice)"},{"id":"B","text":"Diamond ($sp^3$-hybridized tetrahedral crystal lattice)"},{"id":"C","text":"Fullerene ($C_{60}$ soccer-ball molecule)"},{"id":"D","text":"Amorphous carbon soot"}]','"A"',NULL,'A single-walled carbon nanotube (SWCNT) is formed by rolling a single two-dimensional monolayer sheet of graphene (consisting of $sp^2$-hybridized carbon atoms arranged in a 2D honeycomb lattice) into a seamless cylinder with diameters typically between $0.8\text{--}2.0\text{ nm}$.',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2024_024','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,5,'Synthesis Methods (Top-Down vs Bottom-Up)',NULL,'MCQ','Which of the following nanomaterial synthesis techniques is classified as a "Bottom-Up" chemical synthesis method?',NULL,NULL,'[{"id":"A","text":"Sol-Gel Synthesis and Chemical Vapor Deposition (CVD)"},{"id":"B","text":"High-Energy Ball Milling"},{"id":"C","text":"Photolithographic Etching"},{"id":"D","text":"Mechanical Laser Ablation"}]','"A"',NULL,'Bottom-up methods assemble nanostructures atom-by-atom or molecule-by-molecule through chemical reaction and self-assembly (e.g., Sol-Gel, Chemical Vapor Deposition (CVD), Molecular Beam Epitaxy). Top-down methods break down bulk materials mechanically or lithographically (e.g., Ball milling, Lithography, Laser ablation).',NULL,NULL,0,NULL,1,0.25,'easy','UNDERSTAND',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
