INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_PHYSICS_2024_025','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'BE01R00021','Engineering Physics',1,NULL,5,'Photoelectric Effect & Work Function',NULL,'MCQ','Light of frequency $\nu$ illuminates a metal with work function $\Phi_0 = h\nu_0$. According to Einstein''s photoelectric equation, the maximum kinetic energy $K_{\text{max}}$ of emitted photoelectrons is:',NULL,NULL,'[{"id":"A","text":"$K_{\\text{max}} = h\\nu - \\Phi_0 = h(\\nu - \\nu_0)$"},{"id":"B","text":"$K_{\\text{max}} = h\\nu + \\Phi_0$"},{"id":"C","text":"$K_{\\text{max}} = \\frac{h\\nu}{\\Phi_0}$"},{"id":"D","text":"$K_{\\text{max}} = \\frac{1}{2}h\\nu_0$"}]','"A"',NULL,'Einstein''s photoelectric equation states that the incident photon energy $h\nu$ is used in two parts: first to overcome the surface work function barrier $\Phi_0 = h\nu_0$, and the remainder is transferred as the maximum kinetic energy of the liberated electron: $K_{\text{max}} = h\nu - \Phi_0 = h(\nu - \nu_0)$.',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');
INSERT OR IGNORE INTO master_question_bank ("id","source_type","is_original_pyq","is_ai_generated","parent_question_id","provenance_id","source_url","exam_name","exam_year","exam_session","exam_paper_code","question_no","sub_question_no","canonical_subject_id","subject_code","subject_name","semester","curriculum_node_id","unit_no","topic_name","subtopic_name","question_type","question_text","question_html","question_image_url","options_json","correct_answer_json","acceptable_numerical_range_json","explanation","step_by_step_solution_json","latex_formulas_json","diagram_needed","diagram_r2_url","marks","negative_marking","difficulty","bloom_level","tags_json","verification_status","verified_by","verified_at","created_at","updated_at") VALUES('Q_GTU_3110018_2024_025','GTU',1,0,NULL,'gtu_physics_2024',NULL,'GTU',2024,'WINTER',NULL,NULL,NULL,NULL,'3110018','Engineering Physics',1,NULL,5,'Photoelectric Effect & Work Function',NULL,'MCQ','Light of frequency $\nu$ illuminates a metal with work function $\Phi_0 = h\nu_0$. According to Einstein''s photoelectric equation, the maximum kinetic energy $K_{\text{max}}$ of emitted photoelectrons is:',NULL,NULL,'[{"id":"A","text":"$K_{\\text{max}} = h\\nu - \\Phi_0 = h(\\nu - \\nu_0)$"},{"id":"B","text":"$K_{\\text{max}} = h\\nu + \\Phi_0$"},{"id":"C","text":"$K_{\\text{max}} = \\frac{h\\nu}{\\Phi_0}$"},{"id":"D","text":"$K_{\\text{max}} = \\frac{1}{2}h\\nu_0$"}]','"A"',NULL,'Einstein''s photoelectric equation states that the incident photon energy $h\nu$ is used in two parts: first to overcome the surface work function barrier $\Phi_0 = h\nu_0$, and the remainder is transferred as the maximum kinetic energy of the liberated electron: $K_{\text{max}} = h\nu - \Phi_0 = h(\nu - \nu_0)$.',NULL,NULL,0,NULL,1,0.25,'easy','REMEMBER',NULL,'verified','gtu_physics_expert','2026-08-26 19:23:43','2026-08-26 19:23:43','2026-08-26 19:23:43');